from pathlib import Path
import json,copy
r=Path(__file__).resolve().parents[2];out=r/'artifacts/replica/windows-download'
base={'kind':'dmv-ui-sample','version':1,'sample':True,'run':{'id':'UI-SAMPLE1','interrupted':False,'complete':True,'trialSelected':False,'groups':[{'key':'data','total':12,'done':12,'equal':11,'different':1,'unknown':0,'status':'completed'},{'key':'schema','total':18,'done':18,'equal':17,'different':1,'unknown':0,'status':'completed'},{'key':'access','total':8,'done':8,'equal':5,'different':1,'unknown':2,'status':'completed'},{'key':'objects','total':12,'done':12,'equal':12,'different':0,'unknown':0,'status':'completed'}],'tables':['demo.customers','demo.orders','demo.line_items'],'matches':{'demo.customers':'demo.customers','demo.orders':'demo.orders','demo.line_items':'demo.line_items'}},'findings':[]}
cases=[]
def add(id,mutator=None,raw=None):
 value=copy.deepcopy(base)
 if mutator:mutator(value)
 cases.append({'id':id,'raw':raw if raw is not None else json.dumps(value,separators=(',',':'))})
add('saved-valid');add('unknown-input-discard',lambda x:x.update(findings=[{'value':'SYNTHETIC-NEVER-ECHO','password':'SYNTHETIC-NEVER-ECHO'}],extra='SYNTHETIC-NEVER-ECHO'))
add('kind',lambda x:x.update(kind='actual-db'));add('version',lambda x:x.update(version=2));add('sample-false',lambda x:x.update(sample=False));add('duplicate-category',lambda x:x['run']['groups'].append(copy.deepcopy(x['run']['groups'][0])))
add('unknown-category',lambda x:x['run']['groups'][0].update(key='custom'));add('bad-status',lambda x:x['run']['groups'][0].update(status='success'));add('fractional-count',lambda x:x['run']['groups'][0].update(done=1.5));add('integer-exponent',raw=json.dumps(base,separators=(',',':')).replace('"total":12','"total":1.2e1',1));add('integer-decimal',raw=json.dumps(base,separators=(',',':')).replace('"total":12','"total":12.0',1));add('count-overbound',lambda x:x['run']['groups'][0].update(total=10001));add('sum-too-large',lambda x:x['run']['groups'][0].update(equal=12));add('null-id',lambda x:x['run'].update(id=None));add('flag-nonbool',lambda x:x['run'].update(complete=1));add('null-groups',lambda x:x['run'].update(groups=None));add('null-tables',lambda x:x['run'].update(tables=None));add('unknown-table',lambda x:x['run'].update(tables=['private_table']));add('duplicate-table',lambda x:x['run'].update(tables=['demo.orders','demo.orders']));add('match-collision',lambda x:x['run']['matches'].update({'demo.orders':'demo.customers'}));add('null-matches',lambda x:x['run'].update(matches=None));add('false-match',lambda x:x['run']['matches'].update({'demo.orders':False}));add('zero-match',lambda x:x['run']['matches'].update({'demo.orders':0}));add('renamed-match',lambda x:x['run']['matches'].update({'demo.orders':'archive.orders'}));add('bad-json',raw='{');cases.append({'id':'oversize','raw':'{}','oversize':True})
(r/'docs/replica/source/root-pageintegration-file-cases.json').write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
html='''<!doctype html><meta charset="utf-8"><title>Page integration files · original isolation</title><link rel="stylesheet" href="pageintegration-original.css"><div id="app"></div><div id="dialog-host"></div><div id="toast-host"></div><div id="announcer"></div><input id="file-open" hidden type="file"><script src="pageintegration-original.js"></script><button id="files-record" style="position:fixed;z-index:500;top:0;left:0">Record source file behavior</button><script>
const fileCases=CASES;document.getElementById('files-record').onclick=async()=>{const rows=[];for(const c of fileCases){const raw=c.oversize?' '.repeat(1024*1024+1):c.raw;await openFile(new File([raw],'sample.json',{type:'application/json'}));const message=document.getElementById('toast-host').textContent;const accepted=message.startsWith('저장한 예시 결과');rows.push({id:c.id,accepted,message,run:accepted?report().run:null})}const response=await fetch('/evidence/root-pageintegration-mac-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope:'original openFile bounded samples; input extras discarded',rows})});if(!response.ok)throw Error('Evidence failed');document.getElementById('files-record').textContent='File behavior recorded'};
</script>'''.replace('CASES',json.dumps(cases,ensure_ascii=False))
(out/'pageintegration-files.html').write_text(html);print(len(cases))
